/**
 * Ambient types for the in-house storage globals installed by jest.setup.js.
 *
 * Import this module from test helpers that read those globals so TypeScript
 * sees the exact shape the setup file creates.
 */

export interface MockMmkvInstance {
  set(key: string, value: unknown): void;
  getString(key: string): string | undefined;
  getNumber(key: string): number | undefined;
  getBoolean(key: string): boolean | undefined;
  remove(key: string): boolean;
  contains(key: string): boolean;
  getAllKeys(): string[];
  clearAll(): void;
  readonly size: number;
}

declare global {
  var __mmkvGlobalInstance: MockMmkvInstance | undefined;
  var __resetMmkvMock: (() => void) | undefined;
  var __resetAsyncStorageMock: (() => void) | undefined;
  var __resetSecureStoreMock: (() => void) | undefined;
}
